// Generates tokens.css (Tailwind v4 @theme, @font-face, dark mode, reduced motion) and
// theme.native.json (React Native / NativeWind) from tokens.json. `--check` fails when the
// generated files are out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = (file) => fileURLToPath(new URL(file, import.meta.url));
const tokens = JSON.parse(readFileSync(here("./tokens.json"), "utf8"));

const vars = (prefix, group, indent = "  ") =>
  Object.entries(group).map(([name, value]) => `${indent}--${prefix}-${name}: ${value};`);

function fontFaces() {
  return tokens.fontFaces.flatMap((face) => [
    "@font-face {",
    `  font-family: "${face.family}";`,
    "  font-style: normal;",
    `  font-weight: ${face.weight};`,
    "  font-display: swap;",
    `  src: url("${face.file}") format("woff2");`,
    "}",
    "",
  ]);
}

function css() {
  const colors = Object.entries(tokens.color);
  const reduced = Object.keys(tokens.motion.duration).map(
    (name) => `    --duration-${name}: ${tokens.motion.reducedDuration};`,
  );
  return [
    "/* Generated by packages/tokens/build.mjs — edit tokens.json instead. */",
    ...fontFaces(),
    "@theme static {",
    ...colors.map(([name, v]) => `  --color-${name}: ${v.light};`),
    ...vars("font", tokens.font),
    ...vars("radius", tokens.radius),
    ...vars("shadow", tokens.shadow),
    ...vars("spacing", tokens.space),
    ...vars("text", tokens.fontSize),
    ...vars("duration", tokens.motion.duration),
    ...vars("ease", tokens.motion.ease),
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    ...colors.map(([name, v]) => `    --color-${name}: ${v.dark};`),
    "  }",
    "}",
    "",
    "@media (prefers-reduced-motion: reduce) {",
    "  :root {",
    ...reduced,
    "  }",
    "}",
    "",
  ].join("\n");
}

function native() {
  const pick = (mode) => Object.fromEntries(Object.entries(tokens.color).map(([n, v]) => [n, v[mode]]));
  const { font, radius, shadow, space, fontSize, motion } = tokens;
  return (
    JSON.stringify(
      { light: pick("light"), dark: pick("dark"), font, radius, shadow, space, fontSize, motion },
      null,
      2,
    ) + "\n"
  );
}

const outputs = { "./tokens.css": css(), "./theme.native.json": native() };

if (process.argv.includes("--check")) {
  const stale = Object.entries(outputs).filter(([file, text]) => {
    try {
      return readFileSync(here(file), "utf8") !== text;
    } catch {
      return true;
    }
  });
  if (stale.length) {
    console.error(`Out of date: ${stale.map(([f]) => f).join(", ")} — run pnpm --filter @mail-assistant/tokens build`);
    process.exit(1);
  }
} else {
  for (const [file, text] of Object.entries(outputs)) writeFileSync(here(file), text);
}
